<?php
namespace App\Services\Reports\Providers;
use App\Enums\OperationalReportType;use App\Models\SaleInvoice;use App\Models\User;use App\Services\Reports\AbstractOperationalReportProvider;use Illuminate\Contracts\Pagination\CursorPaginator;use Illuminate\Database\Eloquent\Builder;use Illuminate\Support\Carbon;
final class DebtAgingReportProvider extends AbstractOperationalReportProvider{
public function type():OperationalReportType{return OperationalReportType::DEBT_AGING;}protected function label():string{return 'تقرير أعمار الديون';}protected function description():string{return 'الفواتير ذات الأرصدة المتبقية مع تصنيف عمر الدين.';}protected function viewPermission():string{return 'sales.report';}protected function exportPermission():string{return 'sales.export';}protected function scopes():array{return ['network','pos'];}protected function posSelection():string{return 'optional';}protected function statusChoices():array{return ['PARTIALLY_PAID','UNPAID'];}
protected function columns():array{return [['id'=>'invoice_id','label'=>'رقم الفاتورة','data_type'=>'integer'],['id'=>'invoice_uuid','label'=>'مرجع الفاتورة','data_type'=>'text'],['id'=>'invoice_date','label'=>'التاريخ','data_type'=>'date'],['id'=>'pos_id','label'=>'نقطة البيع','data_type'=>'integer'],['id'=>'invoice_total_amount','label'=>'الإجمالي','data_type'=>'decimal'],['id'=>'paid_amount','label'=>'المدفوع','data_type'=>'decimal'],['id'=>'remaining_amount','label'=>'المتبقي','data_type'=>'decimal'],['id'=>'age_days','label'=>'عمر الدين','data_type'=>'integer'],['id'=>'aging_bucket','label'=>'شريحة العمر','data_type'=>'text']];}
protected function metricSlots():array{return [['id'=>'record_count','label'=>'عدد الفواتير','data_type'=>'integer'],['id'=>'total_outstanding','label'=>'إجمالي المديونية','data_type'=>'decimal'],['id'=>'bucket_0_30','label'=>'0–30 يوماً','data_type'=>'decimal'],['id'=>'bucket_31_60','label'=>'31–60 يوماً','data_type'=>'decimal'],['id'=>'bucket_61_90','label'=>'61–90 يوماً','data_type'=>'decimal'],['id'=>'bucket_over_90','label'=>'أكثر من 90 يوماً','data_type'=>'decimal']];}protected function summaryCharts():array{return [['id'=>'debt_aging','label'=>'توزيع المديونية حسب العمر','chart_type'=>'bar','value_key'=>'amount','label_key'=>'bucket']];}
private function query(int $networkId,?int $posId,array $filters):Builder{$p=$this->pattern($filters);$q=SaleInvoice::query()->with('pos')->where('network_id',$networkId)->where('remaining_amount','>',0)->when($posId!==null,fn(Builder $q):Builder=>$q->where('pos_id',$posId))->when($filters['status']??null,fn(Builder $q,string $v):Builder=>$q->where('payment_status',$v))->when($p!==null,fn(Builder $q):Builder=>$q->where('invoice_uuid','like',$p));return $this->applyDates($q,'invoice_date',$filters);}
public function build(User $user,int $networkId,?int $posId,array $filters):CursorPaginator{return $this->paginate($this->query($networkId,$posId,$filters),$filters,'invoice_date','invoice_id');}
private function aging(SaleInvoice $r):array{$age=max(0,Carbon::parse($r->invoice_date)->startOfDay()->diffInDays(now('Asia/Aden')->startOfDay()));$bucket=$age<=30?'0_30':($age<=60?'31_60':($age<=90?'61_90':'over_90'));return ['age_days'=>$age,'aging_bucket'=>$bucket];}
public function summary(User $user,int $networkId,?int $posId,array $filters):array{$rows=$this->query($networkId,$posId,$filters)->get(['invoice_id','invoice_date','remaining_amount']);$b=['0_30'=>0.0,'31_60'=>0.0,'61_90'=>0.0,'over_90'=>0.0];foreach($rows as $r){$a=$this->aging($r);$b[$a['aging_bucket']]+=(float)$r->remaining_amount;}return ['record_count'=>$rows->count(),'total_outstanding'=>$this->amountValue(array_sum($b)),'bucket_0_30'=>$this->amountValue($b['0_30']),'bucket_31_60'=>$this->amountValue($b['31_60']),'bucket_61_90'=>$this->amountValue($b['61_90']),'bucket_over_90'=>$this->amountValue($b['over_90']),'charts'=>['debt_aging'=>[['bucket'=>'0–30','amount'=>$this->amountValue($b['0_30'])],['bucket'=>'31–60','amount'=>$this->amountValue($b['31_60'])],['bucket'=>'61–90','amount'=>$this->amountValue($b['61_90'])],['bucket'=>'>90','amount'=>$this->amountValue($b['over_90'])]]]];}
public function exportColumns():array{return ['invoice_id'=>'رقم الفاتورة','invoice_uuid'=>'مرجع الفاتورة','invoice_date'=>'التاريخ','pos_id'=>'نقطة البيع','invoice_total_amount'=>'الإجمالي','paid_amount'=>'المدفوع','remaining_amount'=>'المتبقي','age_days'=>'عمر الدين','aging_bucket'=>'شريحة العمر'];}
public function serializeExportRow(mixed $r):array{return ['invoice_id'=>$r->invoice_id,'invoice_uuid'=>$r->invoice_uuid,'invoice_date'=>$this->dateValue($r->invoice_date),'pos_id'=>$r->pos_id,'invoice_total_amount'=>$this->amountValue($r->invoice_total_amount),'paid_amount'=>$this->amountValue($r->paid_amount),'remaining_amount'=>$this->amountValue($r->remaining_amount),...$this->aging($r)];}
}